#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# Scope: issue #58 — the human-only setup for the Telegram relay (ADR 0011).
# Everything here is a step a person must do in a browser or in a chat and no
# code can do for them: make the bot, read a user id, stand up the Worker and
# its store, and register the webhook. The wizard captures each value and puts
# it where it belongs, then proves the whole path with a smoke test.
#
# What this wizard does NOT touch, and why:
#   - It never prints the bot token, the webhook secret or the Mac secret to
#     the screen. They are read hidden, generated with no echo, piped straight
#     into `wrangler secret put` and saved to the vault .env. The terminal log
#     is safe to share.
#   - It does not reach into the journal's SQLite file, or carry any broker
#     credential onto the relay (ADR 0011): the relay only ever holds the bot
#     token, the two shared secrets and the allowed user id.
#   - It never deletes the D1 store or re-mints a secret you already have. On a
#     re-run every captured value is offered back, so a half-finished setup is
#     resumed, not restarted. Each action asks before redoing a done step.
VAULT="${VAULT:-$HOME/trading-journal-samples}"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
RELAY_DIR="$REPO_ROOT/relay"
WRANGLER_TOML="$RELAY_DIR/wrangler.toml"
ENV_FILE="$VAULT/.env"

mkdir -p "$VAULT"
chmod 700 "$VAULT"

# wrangler, run from the relay dir so it reads relay/wrangler.toml. Prefer an
# installed binary, else the one in node_modules via npx. Empty when neither is
# available, so each call can fall back to a hand instruction.
WRANGLER=""
if command -v wrangler >/dev/null 2>&1; then
  WRANGLER="wrangler"
elif command -v npx >/dev/null 2>&1; then
  WRANGLER="npx --yes wrangler"
fi

# wrangler_run "desc" ARGS... — run a wrangler command from the relay dir,
# streaming its output. Returns wrangler's exit status; records a manual
# fallback and returns non-zero when wrangler isn't available.
wrangler_run() {
  local desc="$1"; shift
  if [[ -z "$WRANGLER" ]]; then
    SKIPPED+=("$desc — install wrangler (npm i -g wrangler) then: cd relay && wrangler $*")
    warn "wrangler not found — do this by hand later: cd relay && wrangler $*"
    return 1
  fi
  ( cd "$RELAY_DIR" && $WRANGLER "$@" )
}

# gen_secret — a fresh URL-safe secret, from openssl or python3. Printed
# nowhere; only ever written to the vault or piped into wrangler.
gen_secret() {
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -hex 32
  else
    python3 -c 'import secrets; print(secrets.token_hex(32))'
  fi
}

# keep_or_gen KEY — set $KEY to the value already in the vault, or a fresh
# secret saved there. So the webhook secret and the Mac secret stay the same
# across re-runs — both halves (Worker, Telegram, Mac) must agree on them.
keep_or_gen() {
  local key="$1" current
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf -v "$key" '%s' "$current"
    note "reusing the $key already saved in $ENV_FILE"
  else
    printf -v "$key" '%s' "$(gen_secret)"
    write_env "$key" "${!key}"
  fi
}

# set_worker_secret NAME VALUE — pipe a secret into `wrangler secret put` with
# no echo. Records a manual fallback if wrangler is missing.
set_worker_secret() {
  local name="$1" value="$2"
  if [[ -z "$WRANGLER" ]]; then
    SKIPPED+=("Worker secret $name (cd relay && wrangler secret put $name)")
    warn "skipped Worker secret $name — wrangler not ready; set it later"
    return
  fi
  if printf '%s' "$value" | ( cd "$RELAY_DIR" && $WRANGLER secret put "$name" ) >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s Worker secret %s\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("Worker secret $name (cd relay && wrangler secret put $name)")
    warn "couldn't set Worker secret $name — set it by hand: cd relay && wrangler secret put $name"
  fi
}

# doh_resolve HOST — the host's A record over encrypted DNS, so the smoke test
# isn't blinded by the same ISP DNS interception the daily job resolves around
# (relay_client.py, the Flex client). Empty when the lookup can't be made.
doh_resolve() {
  curl -sS -m 15 -H 'accept: application/dns-json' \
    "https://1.1.1.1/dns-query?name=$1&type=A" 2>/dev/null \
    | python3 -c 'import json,sys
try: d = json.load(sys.stdin)
except Exception: sys.exit()
for a in d.get("Answer", []):
    if a.get("type") == 1:
        print(a["data"]); break' 2>/dev/null || true
}

banner "Telegram relay setup (issue #58)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
say "This stands up the Telegram relay (ADR 0011): the one component that runs"
say "off your Mac. It receives the bot's messages and holds your Stop"
say "Declarations until the daily run pulls them. Six manual steps, then a"
say "smoke test that sends a declaration and checks it comes back on a pull."
printf '\n'
missing=0
for t in curl python3; do
  if command -v "$t" >/dev/null 2>&1; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$t"
  else
    printf '  %s✗%s %s\n' "$RED" "$RESET" "$t"; missing=1
  fi
done
(( missing )) && { warn "install the missing tools first"; exit 1; }
if [[ -n "$WRANGLER" ]]; then
  printf '  %s✓%s wrangler (%s)\n' "$GREEN" "$RESET" "$WRANGLER"
else
  printf '  %s○%s wrangler — not found; Cloudflare steps will print manual commands\n' "$YELLOW" "$RESET"
fi
printf '\n'
note "secrets → $ENV_FILE (outside the repo, chmod 700). Nothing secret is"
note "ever printed to this screen."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the bot with BotFather"
say "Open BotFather in Telegram and make a new bot for your journal."
open_url "https://t.me/BotFather"
printf '\n'
step "Send /newbot, then follow the prompts for a name and a @username."
step "BotFather replies with a token like 123456789:AA… — copy it."
printf '\n'
note "The token is a secret: it is read hidden and never shown again."
ask_secret BOT_TOKEN "Paste the bot token:"
if [[ -z "${BOT_TOKEN//[[:space:]]/}" ]]; then
  warn "no token entered."
  [[ ! -t 0 ]] && note "stdin is not a terminal — run this wizard in your own shell."
  exit 1
fi
write_env BOT_TOKEN "$BOT_TOKEN"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Find your Telegram user ID"
say "The relay accepts messages only from your own user ID and drops every"
say "other sender silently (ADR 0011). You need that number next."
open_url "https://t.me/userinfobot"
printf '\n'
step "Open @userinfobot and press Start. It replies with your numeric Id."
printf '\n'
ask TELEGRAM_USER_ID "Paste your Telegram user ID (digits only):"
if ! [[ "$TELEGRAM_USER_ID" =~ ^[0-9]+$ ]]; then
  warn "that is not a plain number — the relay compares it as an integer."
  exit 1
fi
write_env TELEGRAM_USER_ID "$TELEGRAM_USER_ID"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: account, Worker, store and secrets"
say "The relay runs as a Cloudflare Worker over a small D1 store, free-tier"
say "sized. Sign up or log in, then this stage creates the store, sets the"
say "four Worker secrets and deploys."
open_url "https://dash.cloudflare.com/sign-up"
printf '\n'

# Two shared secrets the wizard owns end to end. Generated once, saved, reused.
keep_or_gen WEBHOOK_SECRET
keep_or_gen JOURNAL_SECRET_RELAY_MAC_SECRET
MAC_SECRET="$JOURNAL_SECRET_RELAY_MAC_SECRET"
printf '\n'

if [[ -n "$WRANGLER" ]]; then
  step "Authorise wrangler against your Cloudflare account (opens a browser):"
  if confirm "Run 'wrangler login' now?"; then
    wrangler_run "wrangler login" login || true
  fi
  printf '\n'
fi

# The D1 store. Create it once; paste the database_id wrangler prints and the
# wizard writes it into relay/wrangler.toml, replacing the placeholder.
CURRENT_DB_ID="$(sed -n 's/^database_id *= *"\(.*\)"/\1/p' "$WRANGLER_TOML" 2>/dev/null || true)"
if [[ -n "$CURRENT_DB_ID" && "$CURRENT_DB_ID" != "REPLACE_WITH_D1_DATABASE_ID" ]]; then
  note "wrangler.toml already names database_id $CURRENT_DB_ID"
  confirm "Create a NEW D1 store and replace it?" && CURRENT_DB_ID=""
fi
if [[ -z "$CURRENT_DB_ID" || "$CURRENT_DB_ID" == "REPLACE_WITH_D1_DATABASE_ID" ]]; then
  step "Creating the D1 store 'trading-journal-relay'…"
  wrangler_run "create D1 store" d1 create trading-journal-relay || true
  printf '\n'
  ask D1_DATABASE_ID "Paste the database_id wrangler printed (the uuid):"
  if [[ -n "${D1_DATABASE_ID//[[:space:]]/}" ]]; then
    tmp=$(mktemp)
    sed -e "s/^database_id *=.*/database_id = \"$D1_DATABASE_ID\"/" "$WRANGLER_TOML" > "$tmp" && mv "$tmp" "$WRANGLER_TOML"
    printf '  %s✓ wrote%s database_id → relay/wrangler.toml\n' "$GREEN" "$RESET"
  else
    warn "no database_id entered — set it in relay/wrangler.toml before deploying."
  fi
fi
printf '\n'

step "Applying the store's migration to the remote D1…"
wrangler_run "apply D1 migrations" d1 migrations apply trading-journal-relay --remote || true
printf '\n'

step "Setting the four Worker secrets (nothing is echoed)…"
set_worker_secret TELEGRAM_BOT_TOKEN "$BOT_TOKEN"
set_worker_secret WEBHOOK_SECRET "$WEBHOOK_SECRET"
set_worker_secret MAC_SECRET "$MAC_SECRET"
set_worker_secret TELEGRAM_USER_ID "$TELEGRAM_USER_ID"
printf '\n'

step "Deploying the Worker…"
wrangler_run "deploy the Worker" deploy || true
printf '\n'
say "wrangler prints the live URL on deploy, e.g. https://trading-journal-relay.<you>.workers.dev"
ask JOURNAL_RELAY_URL "Paste the deployed Worker URL:"
JOURNAL_RELAY_URL="${JOURNAL_RELAY_URL%/}"
if ! [[ "$JOURNAL_RELAY_URL" =~ ^https://[^/]+$ ]]; then
  warn "that doesn't look like an https URL — the Mac and Telegram both need it."
  exit 1
fi
write_env JOURNAL_RELAY_URL "$JOURNAL_RELAY_URL"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Register the webhook with Telegram"
say "Point Telegram at the Worker's /telegram endpoint, with the secret token"
say "the relay checks on every call. Done over Telegram's own API, so the bot"
say "token stays off this screen."
printf '\n'
hook_host="${JOURNAL_RELAY_URL#https://}"; hook_host="${hook_host%%/*}"
resolved="$(doh_resolve "api.telegram.org")"
resolve_args=()
[[ -n "$resolved" ]] && resolve_args=(--resolve "api.telegram.org:443:$resolved")
set_resp="$(curl -sS -m 30 "${resolve_args[@]+"${resolve_args[@]}"}" \
  "https://api.telegram.org/bot$BOT_TOKEN/setWebhook" \
  --data-urlencode "url=$JOURNAL_RELAY_URL/telegram" \
  --data-urlencode "secret_token=$WEBHOOK_SECRET" \
  --data-urlencode "allowed_updates=[\"message\"]" || true)"
if printf '%s' "$set_resp" | grep -q '"ok":true'; then
  printf '  %s✓%s webhook registered at %s/telegram\n' "$GREEN" "$RESET" "$hook_host"
else
  warn "setWebhook did not confirm. Telegram replied:"
  printf '\n%s  %s%s\n\n' "$DIM" "$(printf '%s' "$set_resp" | sed -E 's/bot[0-9]+:[A-Za-z0-9_-]+/bot<TOKEN>/g')" "$RESET"
  note "Re-run once the Worker URL is live; saved values are remembered."
  exit 1
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Put the Mac's secrets where the resolver reads them"
say "The daily run reads the relay URL and the Mac secret through the journal's"
say "secrets resolver (job/journal/secrets.py), which looks them up in the"
say "process environment. Both are now saved in the vault:"
printf '\n'
note "  JOURNAL_RELAY_URL              = $JOURNAL_RELAY_URL"
note "  JOURNAL_SECRET_RELAY_MAC_SECRET = (saved in $ENV_FILE, not shown)"
printf '\n'
say "Carry them into the launchd job's environment (deploy/README.md step 1),"
say "so the unattended run resolves them. Paste these into the plist's"
say "EnvironmentVariables, taking the Mac secret's value from the vault:"
printf '\n'
step "export JOURNAL_RELAY_URL=\"$JOURNAL_RELAY_URL\""
step "export JOURNAL_SECRET_RELAY_MAC_SECRET=\"…\"   # value in $ENV_FILE"
printf '\n'
warn "Do not paste the Mac secret anywhere it would be logged — read it from"
warn "the vault file into the plist directly."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Smoke test — declare, then pull it back"
say "This sends a declaration into the relay exactly as Telegram would, pulls"
say "it back the way the Mac does, then acknowledges it so nothing is left for"
say "the daily run. You should also see the bot reply in your own chat."
printf '\n'
resolved="$(doh_resolve "$hook_host")"
pin=()
[[ -n "$resolved" ]] && pin=(--resolve "$hook_host:443:$resolved")

now_epoch="$(date +%s)"
update="$(python3 -c 'import json,sys
uid=int(sys.argv[1]); ts=int(sys.argv[2])
print(json.dumps({"update_id": ts,
  "message": {"from": {"id": uid}, "chat": {"id": uid}, "date": ts, "text": "BBRI 4120"}}))' \
  "$TELEGRAM_USER_ID" "$now_epoch")"

printf '  %s•%s posting a test declaration to %s/telegram\n' "$BLUE" "$RESET" "$hook_host"
hook_code="$(curl -sS -m 30 "${pin[@]+"${pin[@]}"}" -o /dev/null -w '%{http_code}' \
  -X POST "$JOURNAL_RELAY_URL/telegram" \
  -H "x-telegram-bot-api-secret-token: $WEBHOOK_SECRET" \
  -H 'content-type: application/json' \
  --data "$update" || true)"

pass=1
if [[ "$hook_code" == "200" ]]; then
  printf '  %s✓%s webhook accepted the declaration (200)\n' "$GREEN" "$RESET"
else
  printf '  %s✗%s webhook returned %s, expected 200\n' "$RED" "$RESET" "${hook_code:-no response}"; pass=0
fi

printf '  %s•%s pulling it back from %s/pull\n' "$BLUE" "$RESET" "$hook_host"
pull_body="$(curl -sS -m 30 "${pin[@]+"${pin[@]}"}" \
  "$JOURNAL_RELAY_URL/pull" -H "authorization: Bearer $MAC_SECRET" || true)"
ack_id="$(printf '%s' "$pull_body" | python3 -c 'import json,sys
try: items=json.load(sys.stdin).get("items",[])
except Exception: sys.exit()
for it in items:
    if it.get("text")=="BBRI 4120" and it.get("parse",{}).get("kind")=="declaration":
        print(it.get("id","")); break' 2>/dev/null || true)"
if [[ -n "$ack_id" ]]; then
  printf '  %s✓%s the declaration came back on the pull (BBRI 4120, IDX)\n' "$GREEN" "$RESET"
else
  printf '  %s✗%s the declaration did not come back on the pull\n' "$RED" "$RESET"; pass=0
fi

if [[ -n "$ack_id" ]]; then
  printf '  %s•%s acknowledging it so the daily run never sees the test\n' "$BLUE" "$RESET"
  ack_code="$(curl -sS -m 30 "${pin[@]+"${pin[@]}"}" -o /dev/null -w '%{http_code}' \
    -X POST "$JOURNAL_RELAY_URL/ack" -H "authorization: Bearer $MAC_SECRET" \
    -H 'content-type: application/json' --data "{\"ids\":[\"$ack_id\"]}" || true)"
  if [[ "$ack_code" == "204" ]]; then
    printf '  %s✓%s acknowledged; the relay is clean\n' "$GREEN" "$RESET"
  else
    printf '  %s⚠%s ack returned %s — remove the test item by hand if it lingers\n' "$YELLOW" "$RESET" "${ack_code:-no response}"
  fi
fi
printf '\n'
if (( pass )); then
  printf '  %s%s✓ SMOKE TEST PASSED%s — the bot, the relay, its store and both secrets all work.\n' "$BOLD" "$GREEN" "$RESET"
else
  printf '  %s%s✗ SMOKE TEST FAILED%s — the relay is not yet answering as expected.\n' "$BOLD" "$RED" "$RESET"
